      es: ["Altitud destacada de 2494 metros en los Altos Tatras occidentales", "Símbolo nacional oficial, en monedas de euro eslovacas", "Ľudovít Štúr inició el primer ascenso patriótico en 1841", "Tradicionales 'Ascensos Nacionales' cada final de agosto", "Accesible sin guía en rutas marcadas en verano", "Antiguamente hubo actividades de minería de oro en sus laderas", "Inspira a poetas y pintores eslovacos desde el siglo XIX"],
