      fr: ["Altitude marquée de 2494 mètres dans les Hautes Tatras occidentales", "Symbole national officiel, figurant sur les pièces slovaques", "Ľudovít Štúr a initié la première ascension patriotique en 1841", "Traditionnelles 'Ascensions nationales' chaque fin août", "Accessible sans guide sur des sentiers balisés en été", "Anciennement, des activités de recherche d'or sur ses pentes", "Inspire les poètes et peintres slovaques depuis le XIXe siècle"],
