      fr: ["Troisième sommet des Basses Tatras avec 2024 mètres", "Centre de la station de ski de Jasná, la plus grande de Slovaquie", "Accessible toute l'année par des téléphériques Funitel modernes", "Le refuge Kamenná chata offre un abri depuis 1950", "Réputé pour ses conditions météorologiques extrêmes et ses fortes rafales", "Point important de l'itinéraire de randonnée européen E8", "Relie les régions de Liptov et d'Horehronie"],
