      fr: ["Avec 1596 mètres, c'est le plus haut sommet de la Grande Fatra (Veľká Fatra)", "Possède deux sommets presque identiques (nord et sud)", "Une nouvelle mesure en 2016 a confirmé le sommet sud comme le point culminant", "Caractérisé par de vastes paysages de prairies alpines sans arbres", "Historiquement façonné par des siècles de pastoralisme ovin (valaques)", "Terrain prisé pour les longues randonnées à ski en hiver", "Situé au cœur du parc national de Veľká Fatra"],
