      es: "La llanura del Danubio es la parte suroeste de Eslovaquia y forma parte de la Pequeña Llanura Húngara. Es la zona más fértil del país.",
      pt: "A planície do Danúbio é a parte sudoeste da Eslováquia e faz parte da Pequena Planície Húngara. É a zona mais fértil do país.",
      fr: "La plaine du Danube est la partie sud-ouest de la Slovaquie et fait partie de la petite plaine hongroise. C'est la zone la plus fertile du pays.",
