      de: ["Beherbergt den tiefsten Punkt der Slowakei (94m bei Klin nad Bodrogom)", "Nördlichste Ausdehnung der Großen Ungarischen Tiefebene", "Wurde im 20. Jahrhundert durch weitreichende Kanalsysteme trockengelegt", "Im Norden grenzt die Region an das berühmte Tokaj-Weinanbaugebiet", "Die Flüsse Bodrog, Latorica und Laborec prägen die Landschaft", "Bedeutender Lebensraum für Sumpfeichen und seltene Wasservögel", "Zeichnet sich durch ein warmes und trockenes Kontinentalklima aus"],
