      es: ["Alberga el punto más bajo de Eslovaquia (94m en Klin nad Bodrogom)", "Extensión más septentrional de la Gran Llanura Húngara", "Drenado en el siglo XX por amplios sistemas de canales", "En el norte, la región limita con la famosa región vinícola de Tokaj", "Los ríos Bodrog, Latorica y Laborec definen el paisaje", "Hábitat importante para robles de pantano y aves acuáticas raras", "Se caracteriza por un clima continental cálido y seco"],
      pt: ["Abriga o ponto mais baixo da Eslováquia (94m em Klin nad Bodrogom)", "Extensão mais setentrional da Grande Planície Húngara", "Drenado no século XX por amplos sistemas de canais", "No norte, a região limita com a famosa região vinícola de Tokaj", "Os rios Bodrog, Latorica e Laborec definem a paisagem", "Habitat importante para carvalhos de pântano e aves aquáticas raras", "Caracteriza-se por um clima continental quente e seco"],
      fr: ["Abrite le point le plus bas de Slovaquie (94m à Klin nad Bodrogom)", "Extension la plus septentrionale de la Grande plaine hongroise", "Drainée au XXe siècle par de vastes systèmes de canaux", "Au nord, la région borde la célèbre région viticole de Tokaj", "Les rivières Bodrog, Latorica et Laborec définissent le paysage", "Habitat important pour les chênes des marais et les oiseaux aquatiques rares", "Se caractérise par un climat continental chaud et sec"],
