      en: "This mountain range forms the natural border between Slovakia and the Czech Republic. It is famous for its orchid meadows and Flysch geology.",
      es: "Esta cordillera forma la frontera natural entre Eslovaquia y la República Checa. Es conocida por sus praderas de orquídeas y la geología de flysch.",
