    image: "/poi-images/slovakia-male-karpaty-relief-v2.webp",
    descriptionAdvanced: {
      de: "Die Kleinen Karpaten bilden das westlichste Ende des Karpatenbogens in der Slowakei und erstrecken sich von Bratislava bis nach Nové Mesto nad Váhom. Dieses kristalline Gebirge besteht überwiegend aus Granit und Kalkstein, was zur Bildung zahlreicher Höhlen wie der Driny-Höhle geführt hat. Der höchste Gipfel ist der Záruby mit 768 Metern, eingebettet in eine Landschaft aus dichten Laubwäldern. Historisch ist die Region vor allem für den Weinbau entlang der Südosthänge bekannt, der seit der Römerzeit eine tragende wirtschaftliche Säule darstellt. Die strategische Lage des Gebirges wird durch zahlreiche Burgruinen wie Devín, Červený Kameň und Smolenice unterstrichen, die einst die Handelswege schützten. Heute sind die Kleinen Karpaten ein wichtiges Erholungsgebiet für die Hauptstadtregion und bieten ein weit verzweigtes Netz an Wander- und Radwegen.",
      hu: "A Kis-Kárpátok a Kárpátok vonulatának legnyugatibb része Szlovákiában, amely Pozsonytól északkeleti irányban Vágújhelyig húzódik. A hegység magját kristályos kőzetek, gránit és mészkő alkotják, utóbbi kedvezett az olyan karsztjelenségek kialakulásának, mint a látogatható Driny-cseppkőbarlang. Legmagasabb csúcsa a Záruby, amely 768 méteres magasságával emelkedik a sűrű bükk- és tölgyerdők fölé. A délkeleti lejtőkön virágzó borászat a római korig visszanyúló hagyományokkal rendelkezik, és ma a Kis-Kárpáti Borút mentén fedezhető fel. Történelmi jelentőségét számos vár és várrom igazolja, köztük Vöröskő (Červený Kameň) és Szomolány (Smolenice), amelyek egykor a Magyar Királyság határvédelmét látták el. Napjainkban a térség Pozsony és környéke legfontosabb rekreációs övezete, gazdag túraútvonal-hálózattal és kulturális látnivalókkal.",
      ro: "Carpații Mici reprezintă extremitatea vestică a lanțului carpatic pe teritoriul Slovaciei, întinzându-se de la Bratislava până în apropiere de Nové Mesto nad Váhom. Acest masiv muntos este format dintr-un nucleu cristalin de granit, acoperit parțial de calcare și dolomite care au permis formarea peșterii Driny, singura deschisă publicului în această zonă. Vârful Záruby este cel mai înalt punct, având o altitudine de 768 de metri, fiind înconjurat de păduri vaste de foioase. Din punct de vedere economic și cultural, versanții sud-estici sunt faimoși pentru viticultură, tradiție ce datează încă din epoca romană și care definește identitatea locală prin Drumul Vinului din Carpații Mici. Numeroase castele și cetăți, precum Devín sau Červený Kameň, punctează crestele munților, amintind de rolul defensiv strategic pe care l-au avut de-a lungul istoriei în protejarea rutelor comerciale europene.",
      en: "The Little Carpathians constitute the westernmost fringe of the Carpathian arc in Slovakia, stretching from Bratislava towards the northeast to Nové Mesto nad Váhom. This crystalline mountain range is primarily composed of granite and limestone, which has facilitated the creation of karst features such as the Driny Cave, the only cave open to the public in the area. The highest peak is Záruby, reaching an elevation of 768 meters amidst dense deciduous forests of beech and oak. Historically, the southeastern slopes have been a premier wine-growing region since Roman times, now showcased through the Little Carpathian Wine Route. The strategic military importance of the range is evidenced by several well-preserved castles and ruins, including Červený Kameň, Smolenice, and Devín, which historically guarded the Kingdom of Hungary's borders. Today, the range serves as a vital recreational hub for the capital city, offering extensive networks for hiking, cycling, and cultural exploration.",
      es: "Los Pequeños Cárpatos (Malé Karpaty) son una sierra baja en el oeste de Eslovaquia que se extiende desde Bratislava hasta el valle del Váh. El punto más alto es Záruby (767 m). Las montañas consisten en caliza y dolomita, ricas en cuevas y gargantas. Los bosques son predominantemente de hayas y robles. El área es un destino recreativo popular para la capital, con viticultura en las laderas sur. El Parque Natural Malé Karpaty fue designado en 1976. La región tiene una historia rica con castillos como Červený Kameň.",
      pt: "Os Pequenos Cárpatos (Malé Karpaty) são uma serra baixa no oeste da Eslováquia que se estende desde Bratislava até ao vale do Váh. O ponto mais alto é Záruby (767 m). As montanhas consistem em calcário e dolomita, ricas em grutas e desfiladeiros. As florestas são predominantemente de faias e carvalhos. A área é um destino recreativo popular para a capital, com viticultura nas encostas sul. O Parque Natural Malé Karpaty foi designado em 1976. A região tem uma história rica com castelos como Červený Kameň.",
      fr: "Les Petites Carpates (Malé Karpaty) sont un massif montagneux bas dans l'ouest de la Slovaquie, qui s'étend de Bratislava à la vallée du Váh. Le point culminant est le Záruby (767 m). La montagne se compose de calcaire et de dolomite, riche en grottes et en gorges. Les forêts sont principalement constituées de hêtres et de chênes. La zone est une destination de loisirs prisée pour la capitale, avec la viticulture sur les pentes sud. Le parc naturel des Petites Carpates a été désigné en 1976. La région possède une riche histoire avec des châteaux comme celui de Červený Kameň.",
    },
    factsAdvanced: {
      de: ["Der höchste Gipfel Záruby erreicht eine Höhe von 768 Metern.", "Das Gebirge ist etwa 100 Kilometer lang und bis zu 15 Kilometer breit.", "Die Driny-Höhle ist die einzige für Besucher geöffnete Höhle des Gebirges.", "Die Region beherbergt die ältesten Weinbaugebiete der Slowakei.", "Das Landschaftsschutzgebiet Malé Karpaty wurde 1976 gegründet.", "Es trennt das Wiener Becken vom Donautiefland."],
      hu: ["A hegység legmagasabb pontja a Záruby, amely 768 méter magas.", "A vonulat hossza körülbelül 100 kilométer, szélessége pedig 15 kilométer.", "A Driny-barlang az egyetlen látogatható barlang a hegységben.", "Itt található Szlovákia legrégebbi és legjelentősebb borvidéke.", "A Kis-Kárpátok Tájvédelmi Körzetet 1976-ban hozták létre.", "Természetes határt képez a Bécsi-medence és a Dunamenti-alföld között."],
      ro: ["Vârful Záruby este cel mai înalt punct al masivului, având 768 metri.", "Munții se întind pe o lungime de aproximativ 100 de kilometri.", "Peștera Driny a fost descoperită în 1929 și deschisă publicului în 1934.", "Regiunea este cea mai veche zonă viticolă atestată din Slovacia.", "Aria Protejată a Carpaților Mici a fost stabilită oficial în anul 1976.", "Munții adăpostesc Castelul Červený Kameň, ridicat în secolul al XIII-lea."],
      en: ["The highest peak, Záruby, stands at an altitude of 768 meters.", "The mountain range extends approximately 100 kilometers in length.", "Driny Cave is the only karst cave in the range accessible to tourists.", "The region is home to the famous Little Carpathian Wine Route.", "The Malé Karpaty Protected Landscape Area was established in 1976.", "It serves as a geomorphological bridge between the Alps and the Carpathians."],
      es: ["Longitud: 100 km", "Cumbre más alta: Záruby, 767 m", "Superficie de área protegida: 646 km²", "Estatus de protección desde: 1976", "Número de cuevas: 30+", "Superficie de viñedos: 500 ha"],
      pt: ["Comprimento: 100 km", "Cume mais alto: Záruby, 767 m", "Superfície de área protegida: 646 km²", "Estatuto de proteção desde: 1976", "Número de grutas: 30+", "Superfície de vinhedos: 500 ha"],
      fr: ["Longueur : 100 km", "Sommet le plus élevé : Záruby, 767 m", "Superficie de la zone protégée : 646 km²", "Statut de protection depuis : 1976", "Nombre de grottes : 30+", "Superficie des vignobles : 500 ha"],
    },
