      pt: ["Funciona como uma ponte geológica entre Fatra e Tatra", "Não tem uma crista principal contínua e coerente", "A paisagem é fortemente marcada por profundos desfiladeiros de calcário (Kvačianska, Prosiecka)", "Consiste em calcário mesozoico resistente e dolomitas", "Abriga uma flora excecionalmente rica amante de cálcio", "O ponto mais alto e marcante é o pico do Veľký Choč", "Oferece algumas das rotas de caminhada mais pitorescas, mas exigentes"],
      fr: ["Sert de pont géologique entre Fatra et Tatra", "N'a pas de crête principale continue et cohérente", "Le paysage est fortement marqué par des gorges calcaires profondes (Kvačianska, Prosiecka)", "Composé de calcaire mésozoïque résistant et de dolomies", "Abrite une flore calciphile exceptionnellement riche", "Le point culminant et le plus frappant est le sommet du Veľký Choč", "Offre certains des itinéraires de randonnée les plus pittoresques mais exigeants"],
