    imageHint: "Velky Choc peak view",
    image: "/poi-images/slovakia-velky-choc-relief-v2.webp",
    descriptionAdvanced: {
      de: "Der Veľký Choč ist mit 1611 Metern der höchste Gipfel des Choč-Gebirges und gilt als einer der schönsten Aussichtsberge der Slowakei. Seine markante pyramidale Form dominiert die Regionen Liptov und Orava und macht ihn zu einem weithin sichtbaren Orientierungspunkt. Geologisch besteht der Berg hauptsächlich aus Kalkstein und Dolomit, was zu einer zerklüfteten Felslandschaft mit steilen Abhängen geführt hat. Der Aufstieg wird durch eine einzigartige Flora belohnt, die von Relikt-Kiefernwäldern und alpinen Wiesen geprägt ist, auf denen seltene Pflanzenarten gedeihen. Vom Gipfel aus bietet sich ein unvergleichlicher Panoramablick, der von der Hohen und Niederen Tatra bis zur Kleinen und Großen Fatra reicht. Das Gebiet rund um den Gipfel steht seit 1982 unter strengem Naturschutz als nationales Naturreservat, um die empfindlichen Ökosysteme und geologischen Formationen zu bewahren.",
      hu: "A Nagy-Kócs (Veľký Choč) 1611 méteres magasságával a Kócs-hegység legmagasabb csúcsa, és Szlovákia egyik legnépszerűbb kilátópontja. Jellegzetes gúla alakja uralja a Liptói- és az Árvai-medence látképét, messziről felismerhetővé téve a hegyet. Geológiai felépítését főként triász kori mészkő és dolomit alkotja, amely meredek sziklafalak és mély szakadékok kialakulásához vezetett. A hegy növényvilága rendkívül gazdag, havasi gyepek és ritka jégkorszaki maradványfajok (reliktumok) otthona, mint például a havasi gyopár. A csúcsról nyíló körpanoráma egyedülálló, tiszta időben az egész Kárpát-ív központi része belátható tőle a Tátrától a Fatráig. A terület 1982 óta országos természetvédelmi oltalom alatt áll, megőrizve a vidék érintetlen jellegét és biodiverzitását.",
      ro: "Vârful Veľký Choč, având 1611 metri, este cel mai înalt punct din munții Choč și este adesea considerat cel mai bun punct de belvedere din Slovacia. Forma sa piramidală impunătoare domină regiunile Liptov și Orava, oferind un reper vizual clar de la distanțe mari. Din punct de vedere geologic, muntele este format din calcare și dolomite, rezultând un relief carstic spectaculos cu versanți abrupți și formațiuni stâncoase bizare. Vegetația de pe munte este diversă, incluzând păduri de pini relicte și pajiști alpine unde pot fi găsite specii rare de plante protejate. Panorama de pe vârf este neîntreruptă, oferind vederi spectaculoase spre Tatra Înaltă, Tatra Joasă, precum și munții Fatra Mică și Mare. Întreaga zonă somitală a fost declarată rezervație naturală națională în 1982 pentru a proteja integritatea acestui ecosistem montan fragil.",
      en: "Veľký Choč, rising to an elevation of 1611 meters, is the dominant peak of the Choč Mountains and is widely regarded as one of the finest vantage points in Slovakia. Its distinctive pyramidal silhouette towers over the Liptov and Orava basins, serving as a prominent geographical landmark. Geologically, the mountain is composed of Triassic limestone and dolomite, which has created a rugged terrain characterized by steep cliffs and karst formations. The summit area is home to exceptional flora, including relict pine forests and rare alpine plant species that have survived since the last ice age. The panoramic view from the top is unparalleled, offering a clear sight of the High and Low Tatras, as well as the Greater and Lesser Fatra ranges. Since 1982, the summit and its surrounding slopes have been protected as a National Nature Reserve to safeguard its unique biodiversity and geological heritage.",
      es: "El Veľký Choč es una montaña prominente en el oeste de Eslovaquia que se eleva a 1611 m sobre el nivel del mar. Se encuentra en las montañas Chočské vrchy, parte de los Cárpatos occidentales. La montaña consiste en caliza y dolomita y tiene paredes rocosas empinadas. La cima ofrece una vista de 360 grados de los Tatras y los Bajos Tatras. Veľký Choč está protegido como Reserva Natural Nacional. El ascenso es exigente, con un desnivel de 1000 m desde el valle. La flora incluye especies alpinas como el edelweiss y la genciana. La montaña ha sido un área protegida desde 1975.",
      pt: "O Veľký Choč é uma montanha proeminente no oeste da Eslováquia que se eleva a 1611 m acima do nível do mar. Situa-se nas montanhas Chočské vrchy, parte dos Cárpatos Ocidentais. A montanha consiste em calcário e dolomito e tem paredes rochosas íngremes. O cume oferece uma vista de 360 graus dos Tatras e dos Baixos Tatras. Veľký Choč está protegido como Reserva Natural Nacional. A subida é exigente, com um desnível de 1000 m a partir do vale. A flora inclui espécies alpinas como o edelweiss e a genciana. A montanha é uma área protegida desde 1975.",
      fr: "Le Veľký Choč est une montagne proéminente dans l'ouest de la Slovaquie qui s'élève à 1611 m au-dessus du niveau de la mer. Il se situe dans les montagnes Chočské vrchy, faisant partie des Carpates occidentales. La montagne se compose de calcaire et de dolomie et présente des parois rocheuses raides. Le sommet offre une vue à 360 degrés sur les Tatras et les Basses Tatras. Veľký Choč est protégé en tant que Réserve naturelle nationale. L'ascension est exigeante, avec un dénivelé de 1000 m depuis la vallée. La flore comprend des espèces alpines telles que l'edelweiss et la gentiane. La montagne est une zone protégée depuis 1975.",
    },
