      de: ["Der Gipfel des Veľký Choč liegt auf 1611 Metern über dem Meeresspiegel.", "Er ist der höchste Punkt des Choč-Gebirges (Chočské vrchy).", "Das nationale Naturreservat Veľký Choč wurde 1982 ausgewiesen.", "Vom Gipfel aus sind alle bedeutenden slowakischen Gebirgsketten sichtbar.", "Die geologische Basis bilden Kalksteine und Dolomite der Choč-Decke.", "Der beliebteste Aufstiegsweg beginnt im Dorf Valaská Dubová."],
