      es: ["Altura: 1611 m", "Estado de protección: Reserva Natural Nacional desde 1975", "Diferencia de altura con el valle: 1000 m", "Panorama de la cumbre: visibilidad de 100 km", "Composición geológica: 80% caliza", "Cobertura de nieve media: 120 días"],
