      pt: ["Pico mais alto: Strážov", "Numerosas formações rochosas", "Castelo de Bojnice ao pé", "Presença de águas termais"],
      fr: ["Sommet le plus haut : Strážov", "Nombreuses formations rocheuses", "Château de Bojnice au pied", "Présence d'eaux thermales"],
