      es: ["Pico más alto: Vtáčnik", "Vulcanismo de andesita", "Reservas naturales", "Parte de las tierras altas eslovacas"],
      pt: ["Pico mais alto: Vtáčnik", "Vulcanismo de andesito", "Reservas naturais", "Parte das terras altas eslovacas"],
