    imageHint: "Vtacnik mountains forest path",
    image: "/poi-images/slovakia-vtacnik-relief-v2.webp",
    descriptionAdvanced: {
      de: "Der Vtáčnik ist mit 1346 Metern der höchste Gipfel des gleichnamigen Gebirges und stellt den zentralen Teil des slowakischen Mittelgebirges dar. Dieses Gebirge vulkanischen Ursprungs entstand während des Neogens durch intensive magmatische Aktivitäten, was sich heute in beeindruckenden andesitischen Felswänden und Blockfeldern zeigt. Der Gipfelbereich ist von dichten, teils urwaldähnlichen Buchenwäldern bedeckt, die seit 1950 im Rahmen eines staatlichen Naturreservats geschützt sind. Vom markanten Metallkreuz auf dem Gipfel bietet sich ein weiter Ausblick über das obere Nitra-Becken und die umliegenden Gebirgszüge der Fatra. Die Region ist ein bedeutendes Ziel für Wanderer und Bergsteiger, besonders die bizarren Felsformationen von Hrádok sind bei Kletterern sehr beliebt. Trotz seiner wilden Erscheinung ist der Vtáčnik durch ein gut ausgebautes Wegenetz erschlossen, das die Vielfalt der vulkanischen Landschaft erlebbar macht.",
      hu: "A Madaras (Vtáčnik) 1346 méteres magasságával az azonos nevű hegység és a Szlovák-középhegység legmagasabb csúcsa. Ez a vulkáni eredetű hegység a neogén időszakban, intenzív magmatikus tevékenység során alakult ki, amit a látványos andezit sziklafalak és kőtengerek ma is tanúsítanak. A csúcs környékét sűrű, helyenként őserdei jellegű bükkerdők borítják, amelyeket már 1950-ben állami természetvédelmi rezervátummá nyilvánítottak. A csúcson felállított fékereszt mellől pazar kilátás nyílik a Felső-Nyitra-medencére és a környező Fátra vonulataira. A hegység népszerű a túrázók és a sziklamászók körében, különösen a Hrádok nevű andezitfalak vonzzák a sportolókat. A Madaras érintetlen természeti környezete fontos élőhelyet biztosít a kárpáti élővilág számára, miközben jól jelzett túraútvonalak segítik a vulkáni táj felfedezését.",
      ro: "Vârful Vtáčnik, cu o înălțime de 1346 de metri, este cel mai înalt punct al munților cu același nume și reprezintă inima Munților Centrali Slovaci. Masivul este de origine vulcanică, format în perioada neogenă prin procese magmatice intense, care au lăsat în urmă pereți spectaculoși de andezit și câmpuri de blocuri de piatră. Zona somitală este acoperită de păduri de fag cu caracter primar, fiind protejată încă din 1950 ca rezervație naturală de stat. De lângă crucea metalică de pe vârf, vizitatorii pot admira o panoramă vastă asupra bazinului Nitra Superioară și a crestelor munților Fatra. Regiunea este o destinație preferată pentru drumeții și alpinism, formațiunile stâncoase de la Hrádok fiind renumite în comunitatea cățărătorilor. Deși păstrează un aspect sălbatic, muntele Vtáčnik este accesibil printr-o rețea densă de poteci marcate, oferind o incursiune fascinantă în geologia vulcanică a Slovaciei.",
      en: "Vtáčnik, rising to 1346 meters, is the highest peak of its eponymous range and the tallest point within the Slovak Central Mountains. This volcanic range was formed during the Neogene period through significant magmatic activity, leaving behind impressive andesite rock faces and sprawling blockfields. The summit area is shrouded in dense, primeval beech forests, which have been protected as a State Nature Reserve since 1950. From the metal cross at the summit, hikers are rewarded with expansive views over the Upper Nitra Basin and the neighboring Fatra ranges. The mountain is a popular destination for trekking and rock climbing, with the andesite pillars of Hrádok being particularly famous among climbers. Despite its rugged and wild appearance, Vtáčnik is accessible via a well-marked network of trails that showcase the diverse volcanic landscape and its rich Carpathian biodiversity.",
      es: "Las montañas Vtáčnik son una cordillera volcánica en Eslovaquia central. El punto más alto es Vtáčnik con 1346 m. La cordillera se formó en el Terciario y consiste en andesita y toba. Las laderas están cubiertas de bosques de hayas y robles. El área es rica en manantiales y arroyos. El Parque Natural Vtáčnik se estableció en 1970. La región es conocida por su minería (minerales de manganeso). La cima ofrece una amplia vista. La fauna incluye ciervos, jabalíes y, ocasionalmente, lobos.",
      pt: "As montanhas Vtáčnik são uma cordilheira vulcânica na Eslováquia central. O ponto mais alto é Vtáčnik com 1346 m. A cordilheira formou-se no Terciário e consiste em andesito e tufo. As encostas estão cobertas por florestas de faias e carvalhos. A área é rica em nascentes e riachos. O Parque Natural Vtáčnik foi estabelecido em 1970. A região é conhecida pela sua mineração (minérios de manganês). O cume oferece uma vista ampla. A fauna inclui veados, javalis e, ocasionalmente, lobos.",
      fr: "Les montagnes Vtáčnik sont une chaîne de montagnes volcaniques dans le centre de la Slovaquie. Le point le plus haut est Vtáčnik avec 1346 m. La chaîne s'est formée au Tertiaire et se compose d'andésite et de tuf. Les pentes sont couvertes de forêts de hêtres et de chênes. La zone est riche en sources et en ruisseaux. Le parc naturel Vtáčnik a été créé en 1970. La région est connue pour son exploitation minière (minerais de manganèse). Le sommet offre une vue large. La faune comprend des cerfs, des sangliers et, occasionnellement, des loups.",
    },
    factsAdvanced: {
      de: ["Der höchste Gipfel Vtáčnik erreicht eine Höhe von 1346 Metern.", "Das Gebirge ist vulkanischen Ursprungs und besteht aus Andesit.", "Das nationale Naturreservat Vtáčnik wurde bereits 1950 gegründet.", "Es ist das höchste Gebirge des Slowakischen Mittelgebirges.", "Die Felswände von Hrádok sind ein bekanntes Klettergebiet.", "Der Gipfel bietet Ausblicke auf die Niedere Tatra und die Fatra."],
      hu: ["A Madaras (Vtáčnik) legmagasabb pontja 1346 méter.", "A hegység kőzete neogén vulkáni andezit és piroklasztikum.", "A csúcs körüli természetvédelmi területet 1950-ben hozták létre.", "Ez a Szlovák-középhegység (Slovenské stredohorie) legmagasabb tagja.", "A Hrádok sziklafalai Szlovákia egyik legfontosabb mászóhelye.", "A csúcsról tiszta időben az Alacsony-Tátra is látható."],
      ro: ["Vârful Vtáčnik are o altitudine de 1346 metri.", "Masivul s-a format prin activitate vulcanică în epoca Terțiară.", "Rezervația Naturală Națională Vtáčnik a fost stabilită în 1950.", "Este cel mai înalt lanț muntos din grupa Munților Centrali Slovaci.", "Coloanele de andezit de la Hrádok ating înălțimi de peste 50 de metri.", "Munții sunt o barieră naturală între bazinele Nitra și Hron."],
      en: ["Vtáčnik stands at an altitude of 1346 meters above sea level.", "The range is composed of volcanic rocks, primarily andesite.", "The National Nature Reserve was established in 1950.", "It is the highest mountain range in the Slovak Central Mountains.", "The Hrádok rock formation is a major center for Slovak rock climbing.", "The summit is marked by a prominent metal cross."],
      es: ["Pico más alto: Vtáčnik, 1346 m", "Área de reserva natural: 300 km²", "Estado de protección desde: 1970", "Composición geológica: 70% andesita", "Extracción máxima de manganeso: 10.000 t/año", "Manantiales: 50"],
      pt: ["Pico mais alto: Vtáčnik, 1346 m", "Área de reserva natural: 300 km²", "Status de proteção desde: 1970", "Composição geológica: 70% andesito", "Extração máxima de manganês: 10.000 t/ano", "Nascentes: 50"],
      fr: ["Sommet le plus haut : Vtáčnik, 1346 m", "Zone de réserve naturelle : 300 km²", "Statut de protection depuis : 1970", "Composition géologique : 70% andésite", "Extraction maximale de manganèse : 10.000 t/an", "Sources : 50"],
    },
