      es: ["Consiste casi totalmente en caliza clara y dolomita", "Geológicamente completamente diferente de los Altos Tatras vecinos", "Es el área más rica botánicamente y con mayor biodiversidad de Eslovaquia", "El pico más alto es el Havran con 2152 metros de altura", "Por razones de protección natural, está prohibido entrar en casi toda la montaña", "Alberga la cueva de Belianska, la única cueva accesible de los Tatras", "Solo hay un sendero de senderismo legal a través de las montañas"],
      pt: ["Consiste quase totalmente em calcário claro e dolomita", "Geologicamente completamente diferente dos Altos Tatras vizinhos", "É a área mais rica botanicamente e com maior biodiversidade da Eslováquia", "O pico mais alto é o Havran com 2152 metros de altura", "Por razões de proteção natural, é proibido entrar em quase toda a montanha", "Aloja a caverna de Belianska, a única caverna acessível dos Tatras", "Existe apenas um trilho de caminhada legal através das montanhas"],
      fr: ["Composé presque entièrement de calcaire clair et de dolomie", "Géologiquement complètement différent des Hautes Tatras voisines", "C'est la zone la plus riche sur le plan botanique et la plus diversifiée de Slovaquie", "Le sommet le plus élevé est le Havran à 2152 mètres d'altitude", "Pour des raisons de protection de la nature, il est interdit d'entrer dans presque toute la montagne", "Abrite la grotte de Belianska, la seule grotte accessible des Tatras", "Il n'y a qu'un seul sentier de randonnée légal à travers les montagnes"],
