    image: "/poi-images/slovakia-tribec-relief-v2.webp",
    coords: [18.25, 48.47],
    description: {
      de: "Tribeč ist ein bewaldeter Gebirgszug im Westen der Slowakei, der aus kristallinen Gesteinen und Granit besteht. Er ist bekannt für seine dichten Laubwälder und zahlreiche Burgruinen auf den Felsgipfeln.",
      hu: "A Tribecs egy erdős hegység Szlovákia nyugati részén, amely kristályos kőzetekből és gránitból épül fel. Sűrű lombhullató erdőiről és a sziklás csúcsokon álló várromokról ismert.",
      ro: "Munții Tríbeč reprezintă un lanț muntos împădurit din vestul Slovaciei, format din roci cristaline și granit. Sunt cunoscuți pentru pădurile de foioase și numeroasele ruine de castele.",
      en: "Tribeč is a forested mountain range in western Slovakia composed of crystalline rocks and granite. It is known for its dense deciduous forests and numerous medieval castle ruins perched on its rocky peaks.",
      es: "Tribeč es una cadena montañosa boscosa en el oeste de Eslovaquia, compuesta de rocas cristalinas y granito. Es conocida por sus densos bosques caducifolios y numerosas ruinas de castillos en sus cumbres rocosas.",
      pt: "Tribeč é uma cordilheira arborizada no oeste da Eslováquia, composta por rochas cristalinas e granito. É conhecida pelas suas densas florestas caducifólias e inúmeras ruínas de castelos nos cumes rochosos.",
      fr: "Tribeč est une chaîne de montagnes boisée dans l'ouest de la Slovaquie, composée de roches cristallines et de granit. Elle est réputée pour ses forêts de feuillus denses et ses nombreuses ruines de châteaux sur les sommets rocheux.",
    },
