      en: ["The relief includes significant parts of the Western and Eastern Carpathians.", "Gerlachovský štít is the highest peak in the system at 2,655 meters.", "The geology features a mix of granite, limestone, and volcanic rocks.", "It contains major national parks including the High Tatras and Pieniny.", "The mountain ranges were formed primarily during the Alpine orogeny.", "Deep valleys like the Váh and Hron separate the individual belts."],
      es: ["Número de crestas: 13", "Pico más alto: Magurka, 1232 m", "Geología: Flysch (arenisca y lutita)", "Longitud de la cresta principal: aprox. 25 km", "Población ovina: aprox. 5000 animales en la región", "Cabañas turísticas: 3 cabañas gestionadas"],
      pt: ["Número de cristas: 13", "Pico mais alto: Magurka, 1232 m", "Geologia: Flysch (arenito e argilito)", "Comprimento da crista principal: aprox. 25 km", "População de ovelhas: aprox. 5000 animais na região", "Refúgios turísticos: 3 refúgios geridos"],
