      pt: ["Situada no sul da Eslováquia central", "Altitude média entre 150 e 250 m", "Composta pelas partes de Ipeľská, Lučenecká e Rimavská", "Fator económico principal: agricultura", "Massas de ar panónicas quentes moldam o clima", "Base geológica de sedimentos terciários"],
